#!/usr/bin/env python3
# Flugfunk-Kachel in /funk. rtl_airband kommt aus dem Quellcode, nicht aus apt.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEIEN = ("dashboard.py", "prepper_sdr.py", "flugfunk.py")
FEST = {
    "dashboard.py": "4d4a010e6219a8ff",
    "prepper_sdr.py": "3e68a6935c6f0886",
    "flugfunk.py": "49c5d016b06710c2",
    "pushover_push.py": "3916f7d880b13569",
    "pinneberg_rx.py": "c4880894562bd0b7",
}
PAKETE = """===== SCHRITT PAKETE, dieses Skript installiert nichts =====
rtl_airband ist bereits aus Quellcode gebaut:
  /usr/local/bin/rtl_airband
  cmake -DSOAPYSDR=OFF -DPULSEAUDIO=OFF
Nicht apt install rtl-airband.
whisper.cpp selbst bauen, Binary nach /home/fmg/prepper-dashboard/bin/whisper-cli
Modell ggml-base.en.bin nach /home/fmg/prepper-dashboard/models/ggml-base.en.bin
===== ENDE SCHRITT PAKETE ====="""

def load():
    return json.loads(PAYLOAD_TEXT)

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin Minute %02d" % jetzt.minute

def verwandle(data, pairs):
    neu_data = data
    for old, neu, optional in pairs:
        if neu_data.count(neu) >= 1 and neu_data.count(old) == 0:
            continue
        n = neu_data.count(old)
        if n == 0 and optional:
            print("Hinweis: optionale Stelle fehlt, uebersprungen")
            continue
        if n != 1 or neu_data.count(neu) != 0 or old in neu:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-flugfunk2-*"))
    bak = path.with_name(path.name + ".bak-flugfunk2-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-flugfunk2")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def paare():
    roh = load()["pairs"]
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"]), bool(x.get("optional"))) for x in roh[name]] for name in DATEIEN}

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None, hashcheck=True) -> int:
    print(PAKETE)
    liste = paare()
    blobs = {}
    for name in list(DATEIEN) + ["pushover_push.py", "pinneberg_rx.py"]:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            if name in DATEIEN:
                print("STOP: %s fehlt" % name)
                return 2
            print("Hinweis: %s fehlt" % name)
            continue
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
        if hashcheck and not sha(data).startswith(FEST[name]):
            print("STOP: %s ist nicht der Endstand nach apply-flugfunk.py" % name)
            return 2
    try:
        ziel = {name: verwandle(blobs[name], liste[name]) for name in DATEIEN}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    if hashcheck:
        for name, data in ziel.items():
            compile(data, name, "exec")
    if b"_flugfunk_after" not in ziel["dashboard.py"] or b"funk_seite" not in ziel["dashboard.py"]:
        print("STOP: Kachel-Hook fehlt")
        return 2
    if b"kv(box,'Pinneberg'" in ziel["dashboard.py"] or b"Pinneberg: \" + _fua_pin" in ziel["dashboard.py"]:
        print("STOP: Pinneberg-Text bleibt in funkAuf")
        return 2
    if b"Flugfunk" not in ziel["prepper_sdr.py"]:
        print("STOP: Aufteilung ohne Flugfunk")
        return 2
    if b"/usr/local/bin/rtl_airband" not in ziel["flugfunk.py"] or b"def funk_seite" not in ziel["flugfunk.py"]:
        print("STOP: funk_seite fehlt")
        return 2
    seite = "<html><body><p>Stick 3 · Pinneberg</p></body></html>"
    # Die Kachel-Pruefung liegt im Modul-Selbsttest. Hier nur die Zeichen im neuen HTML-Helfer.
    if b'id="flugfunkBox"' not in ziel["flugfunk.py"] or b"ffPush" not in ziel["flugfunk.py"] or b"ffLive" not in ziel["flugfunk.py"]:
        print("STOP: Kachel unvollstaendig")
        return 2
    print("funk-HTML enthaelt die Kachel, sobald funk_seite laeuft")
    for name in DATEIEN:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    if all(blobs[name] == ziel[name] for name in DATEIEN):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        print("Pruefung: curl -sS http://127.0.0.1:5000/funk | grep -c flugfunkBox")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in DATEIEN:
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError):
        print("STOP beim Schreiben")
        return 3
    print("geschrieben. Kachel ueber _flugfunk_after und funkAuf.")
    if kein or ordner != DASH:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt aus.")
        return 2
    lauf = __import__("subprocess").run
    lauf(["systemctl", "restart", "prepper-sdr.service"], check=False)
    lauf(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Neu gestartet: prepper-sdr, prepper-dashboard.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 21, 12, 5))[0]
    assert fenster(datetime(2026, 11, 21, 12, 39))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 4))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 40))[0]
    import tempfile
    liste = paare()
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk2-"))
    for name in DATEIEN:
        (ordner / name).write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12), hashcheck=False) == 2
    assert (ordner / "dashboard.py").read_bytes() == b"UNBERUEHRT"
    inhalt = {}
    for name, pairs in liste.items():
        teile = []
        for i, (old, neu, optional) in enumerate(pairs):
            assert old not in neu
            teile.append(old)
            teile.append(b"\n# trenn %d\n" % i)
        blob = b"".join(teile)
        (ordner / name).write_bytes(blob)
        inhalt[name] = blob
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12), hashcheck=False) == 0
    assert all((ordner / name).read_bytes() == inhalt[name] for name in DATEIEN)
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 4), hashcheck=False) == 2
    assert all((ordner / name).read_bytes() == inhalt[name] for name in DATEIEN)
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12), hashcheck=False) == 0
    dash = (ordner / "dashboard.py").read_bytes()
    funk = (ordner / "flugfunk.py").read_bytes()
    assert b"_flugfunk_after" in dash and b"funk_seite" in dash
    assert b'id="flugfunkBox"' in funk and b"ffPush" in funk and b"ffLive" in funk and b"Live h" in funk
    # /funk-HTML: die Kachelfunktion aus der geschriebenen Datei
    roh = base64.b64decode(load()["flugfunk_neu"])
    ns = {"__name__": "flugfunk"}
    exec(compile(roh, "flugfunk.py", "exec"), ns)
    seite = ns["funk_seite"]("<html><body><p>Stick 3 · Pinneberg</p></body></html>")
    assert seite.count('id="flugfunkBox"') == 1
    assert "ffPush" in seite and "Kachelalarm" in seite and "ffLive" in seite and "Live hören" in seite
    assert ns["funk_seite"](seite) == seite
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12), hashcheck=False) == 0
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

